INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 17, 'theory', 'Quiz: RAID and SMART');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 0, 'Four 4 TB disks form a raid5. What is the usable capacity and how many failures does the array survive for sure?', '["16 TB and two failures", "8 TB and one failure", "12 TB and one failure", "12 TB and two failures"]', 2, 'RAID5 keeps one parity: the capacity is N-1 disks, that is 12 TB, and one failure for sure. Only raid6 survives two.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 1, 'What does "[4/3] [UUU_]" in /proc/mdstat mean?', '["Three arrays out of four work", "The array is 75 percent synchronized", "The fourth disk is a hot spare", "Four disks are expected, three work, the fourth dropped out"]', 3, 'The first number is how many disks there should be, the second how many work; the underscore in the string of U letters stands in place of the missing disk. Synchronization percentages are on a separate line.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 2, 'In what order do you replace the failed disk sdc1 in the array md0?', '["--fail, --remove, swap the disk, --add", "--add, --remove, --fail, swap the disk", "Swap the disk, --remove, --add, --fail", "--remove, swap the disk, --fail, --add"]', 0, 'An active member cannot be removed: first it is marked failed, then removed, the hardware is swapped and only then is the new disk added, after which the rebuild starts.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 3, 'smartctl -H prints PASSED, but the raw values of attributes 197 and 198 are 8. What is sensible?', '["Nothing: PASSED means the disk is healthy", "Watch the growth and prepare a replacement: PASSED only says no threshold was crossed", "Reboot the server so the counters reset", "Turn SMART off in the disk settings"]', 1, 'PASSED does not mean the disk is healthy: the thresholds of pre-failure attributes are often far away, while nonzero pending and uncorrectable sectors are a real sign of wear. A reboot does not reset the counters.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 17, 4, 'Which field of the NVMe health block shows the share of the drive''s life used?', '["Available Spare", "Critical Warning", "Percentage Used", "Unsafe Shutdowns"]', 2, 'Percentage Used is the vendor''s estimate of how much life is consumed; 100 means the rated endurance is used up. Available Spare shows the remaining spare blocks and Critical Warning is a set of alarm bits.');
